--------------------------------------------------------------------------------
-- File:         test/test_usage.lua
--
-- Description:  the help text is a GENERATED file and must not go stale
--
--               src/lexiftool/usage.lua is not maintained by hand: it is the
--               vendored exiftool's own help output with this port's names
--               substituted (tools/usage_rules.lua, regenerated by
--               `make usage`). Update vendor/exiftool and the generated file is
--               silently out of date -- unless something checks.
--
--               Two checks:
--                 1. the generated file still matches what the rules produce
--                    from the vendored help (needs perl; skipped with a notice
--                    when it is unavailable)
--                 2. `lexiftool --help` actually prints that file
--
--               This lives here, not in the CLI comparison, on purpose. The
--               port deviates from upstream's help text deliberately, so
--               comparing the two would need a tool-specific rewrite inside the
--               comparison -- the one asymmetry that harness must not have. And
--               "a generated file is stale" is a build-freshness question, so
--               it belongs in `make check`, which gates, rather than in the
--               report-only CLI run.
--------------------------------------------------------------------------------

local TestLib = require('test.TestLib')
local ok = TestLib.ok

local REPO_DIR = TestLib.REPO_DIR
local USAGE = require('lexiftool.usage')

-- cmd.exe (io.popen's shell on Windows) knows no single-quote quoting and
-- has no /dev/null; double quotes and NUL are its equivalents (the paths
-- quoted here are plain filesystem paths, never containing a double quote)
local isWindows = package.config:sub(1, 1) == '\\'

local function shquote(s)
    if isWindows then return '"' .. s .. '"' end
    return "'" .. s:gsub("'", [['\'']]) .. "'"
end

-- Both texts are thousands of lines; report the first divergence instead of
-- dumping them.
local function firstDiff(expected, got)
    local a, b = {}, {}
    for line in (expected .. '\n'):gmatch('([^\n]*)\n') do a[#a + 1] = line end
    for line in (got .. '\n'):gmatch('([^\n]*)\n') do b[#b + 1] = line end
    for i = 1, math.max(#a, #b) do
        if a[i] ~= b[i] then
            return ('first difference at line %d: expected %q, got %q')
                :format(i, tostring(a[i]), tostring(b[i]))
        end
    end
    return ('same lines but %d vs %d bytes'):format(#expected, #got)
end

-- cmd.exe's documented /c quote rule, "old behavior" branch: when the
-- command line starts with a quote and holds more than two quotes, cmd
-- strips the FIRST and the LAST quote of the line. Without wrapping, the
-- last quote is the one closing the script path, leaving the broken program
-- name `...\lua.exe" "D:\...\lexiftool` behind -- cmd reports that as
-- "The filename, directory name, or volume label syntax is incorrect".
-- Wrapping the whole line, redirects included, in one more outer pair makes
-- cmd strip exactly that pair and keep the command's own quotes intact.
-- shquote above always quotes on Windows, so there are always more than two
-- quotes and this branch always applies; Unix shells have no such rule, so
-- no wrapping there.
local function wrap(line)
    if not isWindows then return line end
    return '"' .. line .. '"'
end

local function capture(cmd)
    local null = isWindows and 'NUL' or '/dev/null'
    local pipe = io.popen(wrap(cmd .. ' 2>' .. null .. ' < ' .. null))
    if not pipe then return nil end
    local out = pipe:read('a')
    pipe:close()
    return out
end

-- stderr merged in, for a failure message only (never for the real
-- stdout-only comparison above): shows e.g. "command not found" instead
-- of a silent empty capture
local function captureWithStderr(cmd)
    local null = isWindows and 'NUL' or '/dev/null'
    local pipe = io.popen(wrap(cmd .. ' 2>&1 < ' .. null))
    if not pipe then return nil end
    local out = pipe:read('a')
    pipe:close()
    return out
end

--------------------------------------------------------------------------------
-- 1. The generated file matches the vendored upstream help
--------------------------------------------------------------------------------
do
    local perlExifTool = REPO_DIR .. '/vendor/exiftool/exiftool'
    local perlLib = REPO_DIR .. '/vendor/exiftool/lib'
    local original = capture('perl -I ' .. shquote(perlLib) .. ' ' ..
                             shquote(perlExifTool) .. ' --help') or ''
    if #original < 1000 then
        -- Same threshold gen_usage.lua uses to detect "perl did not run".
        ok(true, 'usage.lua freshness SKIPPED (perl or vendored exiftool unavailable)')
    else
        local rules = dofile(REPO_DIR .. '/tools/usage_rules.lua')
        local expected, warn = rules.transform(original)
        ok(warn == nil, 'usage rules applied without warning: ' .. tostring(warn))
        ok(expected == USAGE,
           'usage.lua is up to date with vendor/exiftool (else run `make usage`) -- ' ..
           (expected == USAGE and 'ok' or firstDiff(expected, USAGE)))
    end
end

--------------------------------------------------------------------------------
-- 2. The CLI prints it
--------------------------------------------------------------------------------
do
    -- Same interpreter and module path this test runs under, so the CLI
    -- resolves the very module compared above.
    local interp = TestLib.LUA or 'lua'
    local cmd = shquote(interp) .. ' ' .. shquote(REPO_DIR .. '/lexiftool') .. ' --help'
    local printed = capture(cmd)
    ok(printed == USAGE,
       'lexiftool --help prints usage.lua -- ' ..
       (printed == USAGE and 'ok' or
        ('cmd: ' .. cmd .. ' -- ' .. firstDiff(USAGE, printed or '<no output>') ..
         ' -- stderr: ' .. tostring(captureWithStderr(cmd)))))
end
